function removeDuplicates(s) {
  const stack = [];
  for (const ch of s) {
    if (stack.length > 0 && stack[stack.length - 1] === ch) {
      stack.pop();          // ch cancels the letter right before it
    } else {
      stack.push(ch);
    }
  }
  return stack.join("");
}

def remove_duplicates(s):
    stack = []
    for ch in s:
        if stack and stack[-1] == ch:
            stack.pop()           # ch cancels the letter right before it
        else:
            stack.append(ch)
    return "".join(stack)

String removeDuplicates(String s) {
    StringBuilder stack = new StringBuilder();   // a StringBuilder works as a stack of chars
    for (char ch : s.toCharArray()) {
        int top = stack.length() - 1;
        if (top >= 0 && stack.charAt(top) == ch) {
            stack.deleteCharAt(top);     // ch cancels the letter right before it
        } else {
            stack.append(ch);
        }
    }
    return stack.toString();
}

string removeDuplicates(const string& s) {
    string stack;                        // a string works as a stack of chars
    for (char ch : s) {
        if (!stack.empty() && stack.back() == ch) {
            stack.pop_back();            // ch cancels the letter right before it
        } else {
            stack.push_back(ch);
        }
    }
    return stack;
}
